import tempfile
import torch
import torch.nn as nn
from topologies import Trainer, build, synth
root = tempfile.mkdtemp()
@synth.generator
def triplets(ctx):
    anchor = torch.randn(4, generator=ctx.rng.torch)
    positive = anchor + 0.05 * torch.randn(4, generator=ctx.rng.torch)
    negative = torch.randn(4, generator=ctx.rng.torch)
    return {'inputs': torch.stack((anchor, positive, negative)), 'anchor_target': anchor}
class TripletEncoder(nn.Module):
    def __init__(self):
        super().__init__()
        self.encoder = build('mlp', 'tiny', in_features=4, out_features=3)
    def forward(self, x):
        return {'anchor': self.encoder(x[:, 0]), 'positive': self.encoder(x[:, 1]), 'negative': self.encoder(x[:, 2])}
ds = synth.Spec('triplet-data', generator=triplets, size=24, splits={'train': 0.75, 'val': 0.25}, seed=7, root=root, monitor='none').run()
train = ds.for_recipe('structured-objective', split='train')
val = ds.for_recipe('structured-objective', split='val', like=train)
trainer = Trainer(TripletEncoder(), train, val, recipe='structured-objective', recipe_config={'loss': 'triplet-margin', 'bindings': {'anchor': {'output': 'anchor'}, 'positive': {'output': 'positive'}, 'negative': {'output': 'negative'}}}, batch_size=8, max_epochs=1, device='cpu')
trainer.fit()
assert all(torch.isfinite(torch.tensor(v)) for v in trainer.evaluate(val).values())
